      ro: "O colecție de mausolee construite de împărații dinastiei Ming. Treisprezece din cei șaisprezece împărați Ming sunt îngropați aici.",
      en: "A collection of mausoleums built by the emperors of the Ming dynasty. Thirteen of the sixteen Ming emperors are buried here.",
      es: "Un conjunto de mausoleos construidos por los emperadores de la dinastía Ming. Aquí están enterrados trece de los dieciséis emperadores Ming.",
      pt: "Uma coleção de mausoléus construídos pelos imperadores da dinastia Ming. Treze dos dezesseis imperadores Ming estão enterrados aqui.",
      fr: "Un ensemble de mausolées construits par les empereurs de la dynastie Ming. Treize des seize empereurs Ming y sont enterrés.",
